#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<int> inputs(2);
    for (int i = 0; i < 2; ++i) {
        cin >> inputs[i];
    }
    sort(inputs.begin(), inputs.end());
    int n = inputs[0];
    int m = inputs[1];

    int delta_value;
    if (n == 1) {
        delta_value = min(m % 6, 6 - m % 6);
    } else if (n == 2) {
        map<int, int> delta_map = {{2, 4}, {3, 2}, {7, 2}};
        delta_value = delta_map.count(m) ? delta_map[m] : 0;
    } else {
        delta_value = (n & 1) * (m & 1);
    }

    cout << n * m - delta_value << "\n";
    return 0;
}
